import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Container, Row, Col, Card, Button, Navbar, Nav, Form, InputGroup, Badge, Modal, Table, Alert, Spinner } from 'react-bootstrap';
import 'bootstrap/dist/css/bootstrap.min.css';
import './App.css';

const API_URL = 'http://localhost:5000/api';

function App() {
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);
  const [user, setUser] = useState(null);
  const [showLogin, setShowLogin] = useState(false);
  const [showCart, setShowCart] = useState(false);
  const [showCheckout, setShowCheckout] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isLogin, setIsLogin] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [loading, setLoading] = useState(true);
  
  const [shippingDetails, setShippingDetails] = useState({
    fullName: '',
    address: '',
    city: '',
    state: '',
    pincode: '',
    phone: '',
    paymentMethod: 'cod'
  });

  // 20+ Products with Indian prices
  const allProducts = [
    { id: 1, name: "Apple AirPods Pro", price: 24999, description: "Active Noise Cancellation, Transparency mode, Spatial audio, MagSafe charging case", category: "Electronics", image: "https://images.unsplash.com/photo-1588423771073-b8903fbb85b5?w=400", stock: 25, rating: 4.8, brand: "Apple" },
    { id: 2, name: "Sony WH-1000XM5", price: 29999, description: "Industry-leading noise cancellation, 30-hour battery life, Premium sound quality", category: "Electronics", image: "https://images.unsplash.com/photo-1618366712010-f4ae9c647dcb?w=400", stock: 15, rating: 4.9, brand: "Sony" },
    { id: 3, name: "iPhone 15 Pro", price: 134900, description: "A17 Pro chip, Titanium design, 48MP main camera, USB-C, 5G ready", category: "Electronics", image: "https://images.unsplash.com/photo-1696446701796-da61225697cc?w=400", stock: 10, rating: 4.9, brand: "Apple" },
    { id: 4, name: "Samsung Galaxy S24 Ultra", price: 129999, description: "AI-powered, 200MP camera, S Pen included, 7 years of updates", category: "Electronics", image: "https://images.unsplash.com/photo-1610945265064-0e34e5519bbf?w=400", stock: 12, rating: 4.8, brand: "Samsung" },
    { id: 5, name: "MacBook Pro M3", price: 169900, description: "M3 chip, 14-inch Liquid Retina XDR, 18GB RAM, 512GB SSD", category: "Electronics", image: "https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=400", stock: 8, rating: 4.9, brand: "Apple" },
    { id: 6, name: "Nike Air Max Shoes", price: 12999, description: "Comfortable running shoes with Air Max cushioning, breathable mesh", category: "Clothing", image: "https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=400", stock: 40, rating: 4.6, brand: "Nike" },
    { id: 7, name: "Levi's Jeans", price: 3999, description: "Premium denim jeans, slim fit, comfortable cotton, 5-pocket styling", category: "Clothing", image: "https://images.unsplash.com/photo-1541099649105-f69ad21f3246?w=400", stock: 50, rating: 4.5, brand: "Levi's" },
    { id: 8, name: "Peter England Shirt", price: 2499, description: "Formal cotton shirt, wrinkle-free, premium quality, regular fit", category: "Clothing", image: "https://images.unsplash.com/photo-1596755094514-f87e34085b2c?w=400", stock: 35, rating: 4.4, brand: "Peter England" },
    { id: 9, name: "Fossil Gen 6 Watch", price: 22999, description: "Smart watch with Wear OS, heart rate tracking, GPS, AMOLED display", category: "Accessories", image: "https://images.unsplash.com/photo-1524805444758-089113d48a6d?w=400", stock: 20, rating: 4.7, brand: "Fossil" },
    { id: 10, name: "Titan Analog Watch", price: 8999, description: "Elegant analog watch with stainless steel strap, water resistant", category: "Accessories", image: "https://images.unsplash.com/photo-1522312346375-d1a52e2b99b3?w=400", stock: 30, rating: 4.5, brand: "Titan" },
    { id: 11, name: "Noise Smart Watch", price: 3999, description: "1.96 AMOLED display, Bluetooth calling, IP68, 7-day battery", category: "Accessories", image: "https://images.unsplash.com/photo-1579586337278-3befd40fd17a?w=400", stock: 45, rating: 4.3, brand: "Noise" },
    { id: 12, name: "OnePlus Nord CE 4", price: 24999, description: "6.7-inch display, 50MP camera, 5000mAh battery, 5G ready", category: "Electronics", image: "https://images.unsplash.com/photo-1610792516307-ea5acd9c3b6d?w=400", stock: 22, rating: 4.6, brand: "OnePlus" },
    { id: 13, name: "Realme GT 6T", price: 30999, description: "Snapdragon 7+ Gen 3, 120W charging, 50MP camera", category: "Electronics", image: "https://images.unsplash.com/photo-1610945415295-d9bbf067e59c?w=400", stock: 18, rating: 4.7, brand: "Realme" },
    { id: 14, name: "Puma T-Shirt", price: 1499, description: "Cotton blend t-shirt, regular fit, sports style, breathable fabric", category: "Clothing", image: "https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=400", stock: 60, rating: 4.4, brand: "Puma" },
    { id: 15, name: "Adidas Track Pant", price: 2999, description: "Comfortable track pants for daily wear, elastic waistband", category: "Clothing", image: "https://images.unsplash.com/photo-1556906781-9a412961c28c?w=400", stock: 55, rating: 4.5, brand: "Adidas" },
    { id: 16, name: "Boat Airdopes 441", price: 1799, description: "Wireless earbuds with 40h battery life, ENx technology", category: "Electronics", image: "https://images.unsplash.com/photo-1606220588913-b3aacb4d2f46?w=400", stock: 100, rating: 4.3, brand: "Boat" },
    { id: 17, name: "Mi Band 9", price: 3999, description: "Fitness tracker with AMOLED display, 14-day battery", category: "Accessories", image: "https://images.unsplash.com/photo-1575311373937-040b8e1fd5b6?w=400", stock: 75, rating: 4.6, brand: "Xiaomi" },
    { id: 18, name: "Fastrack Backpack", price: 2499, description: "Durable backpack with laptop compartment, USB charging port", category: "Accessories", image: "https://images.unsplash.com/photo-1553062407-98eeb64c6a62?w=400", stock: 40, rating: 4.4, brand: "Fastrack" },
    { id: 19, name: "Ray-Ban Sunglasses", price: 7999, description: "Classic aviator sunglasses, UV protection, polarized lenses", category: "Accessories", image: "https://images.unsplash.com/photo-1511499767150-a48a237f0083?w=400", stock: 25, rating: 4.8, brand: "Ray-Ban" },
    { id: 20, name: "Nike Sports Shoes", price: 8999, description: "Running shoes with responsive cushioning, breathable mesh", category: "Clothing", image: "https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=400", stock: 35, rating: 4.7, brand: "Nike" },
    { id: 21, name: "Canon EOS R50", price: 64999, description: "Mirrorless camera, 24.2MP, 4K video, RF mount", category: "Electronics", image: "https://images.unsplash.com/photo-1504208434309-cb69f4fe52b0?w=400", stock: 8, rating: 4.8, brand: "Canon" },
    { id: 22, name: "Dell XPS 15", price: 159999, description: "Intel Core i7, 32GB RAM, 1TB SSD, RTX 4070", category: "Electronics", image: "https://images.unsplash.com/photo-1593642632823-8f785ba67e45?w=400", stock: 6, rating: 4.9, brand: "Dell" },
    { id: 23, name: "Zara Women's Dress", price: 3999, description: "Floral print maxi dress, comfortable fabric, elegant design", category: "Clothing", image: "https://images.unsplash.com/photo-1539008835657-9e8e9680c956?w=400", stock: 30, rating: 4.6, brand: "Zara" },
    { id: 24, name: "H&M Hoodie", price: 2499, description: "Oversized hoodie, cotton blend, kangaroo pocket", category: "Clothing", image: "https://images.unsplash.com/photo-1556821840-3a63f95609a7?w=400", stock: 45, rating: 4.5, brand: "H&M" }
  ];

  useEffect(() => {
    setProducts(allProducts);
    setLoading(false);
    const token = localStorage.getItem('token');
    if (token) {
      const userData = JSON.parse(localStorage.getItem('user') || '{}');
      setUser(userData);
    }
  }, []);

  const formatIndianRupee = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(amount);
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    if (!isLogin) {
      const newUser = { id: Date.now(), name, email, isAdmin: false };
      localStorage.setItem('token', 'dummy-token');
      localStorage.setItem('user', JSON.stringify(newUser));
      setUser(newUser);
      setShowLogin(false);
      alert('Registration successful!');
    } else {
      if (email === 'demo@example.com' && password === 'demo') {
        const userData = { id: 1, name: 'Demo User', email, isAdmin: false };
        localStorage.setItem('token', 'dummy-token');
        localStorage.setItem('user', JSON.stringify(userData));
        setUser(userData);
        setShowLogin(false);
        alert('Login successful!');
      } else {
        alert('Demo credentials: demo@example.com / demo');
      }
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
    setCart([]);
    alert('Logged out successfully');
  };

  const addToCart = (product) => {
    const existingItem = cart.find(item => item.id === product.id);
    if (existingItem) {
      setCart(cart.map(item => 
        item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
      ));
    } else {
      setCart([...cart, { ...product, quantity: 1 }]);
    }
  };

  const removeFromCart = (productId) => {
    setCart(cart.filter(item => item.id !== productId));
  };

  const updateQuantity = (productId, newQuantity) => {
    if (newQuantity < 1) {
      removeFromCart(productId);
    } else {
      setCart(cart.map(item =>
        item.id === productId ? { ...item, quantity: newQuantity } : item
      ));
    }
  };

  const getCartTotal = () => {
    return cart.reduce((total, item) => total + (item.price * item.quantity), 0);
  };

  const getCartCount = () => {
    return cart.reduce((count, item) => count + item.quantity, 0);
  };

  const handleCheckoutInput = (e) => {
    setShippingDetails({
      ...shippingDetails,
      [e.target.name]: e.target.value
    });
  };

  const placeOrder = () => {
    if (!shippingDetails.fullName || !shippingDetails.address || !shippingDetails.city || 
        !shippingDetails.pincode || !shippingDetails.phone) {
      alert('Please fill all shipping details');
      return;
    }
    
    alert(`✅ Order placed successfully!\n\nTotal: ${formatIndianRupee(getCartTotal())}\nPayment: ${shippingDetails.paymentMethod === 'cod' ? 'Cash on Delivery' : 'Online Payment'}\n\nThank you for shopping with ShopHub India!`);
    setCart([]);
    setShowCart(false);
    setShowCheckout(false);
    setShippingDetails({
      fullName: '', address: '', city: '', state: '', pincode: '', phone: '', paymentMethod: 'cod'
    });
  };

  const filteredProducts = products.filter(product => {
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const categories = ['All', ...new Set(products.map(p => p.category))];

  return (
    <div className="app">
      {/* Navigation Bar */}
      <Navbar bg="dark" variant="dark" expand="lg" sticky="top" className="shadow">
        <Container>
          <Navbar.Brand href="#" className="d-flex align-items-center">
            <i className="bi bi-shop fs-3 me-2"></i>
            <span className="fw-bold fs-4">ShopHub India</span>
          </Navbar.Brand>
          <Navbar.Toggle aria-controls="basic-navbar-nav" />
          <Navbar.Collapse id="basic-navbar-nav">
            <Form className="mx-auto w-50">
              <InputGroup>
                <InputGroup.Text><i className="bi bi-search"></i></InputGroup.Text>
                <Form.Control
                  type="text"
                  placeholder="Search products..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </InputGroup>
            </Form>
            <Nav className="ms-auto align-items-center gap-2">
              <Button variant="outline-light" onClick={() => setShowCart(true)} className="position-relative">
                <i className="bi bi-cart3"></i> Cart
                {getCartCount() > 0 && (
                  <Badge bg="danger" pill className="position-absolute top-0 start-100 translate-middle">
                    {getCartCount()}
                  </Badge>
                )}
              </Button>
              {user ? (
                <div className="d-flex gap-2 align-items-center">
                  <span className="text-light">
                    <i className="bi bi-person-circle"></i> Hello, {user.name}
                  </span>
                  <Button variant="outline-danger" size="sm" onClick={handleLogout}>
                    <i className="bi bi-box-arrow-right"></i> Logout
                  </Button>
                </div>
              ) : (
                <Button variant="primary" onClick={() => setShowLogin(true)}>
                  <i className="bi bi-person"></i> Login
                </Button>
              )}
            </Nav>
          </Navbar.Collapse>
        </Container>
      </Navbar>

      {/* Category Filter */}
      <div className="category-bar bg-light py-3 border-bottom shadow-sm">
        <Container>
          <div className="d-flex gap-2 flex-wrap justify-content-center">
            {categories.map(category => (
              <Button
                key={category}
                variant={selectedCategory === category ? "primary" : "outline-secondary"}
                size="sm"
                onClick={() => setSelectedCategory(category)}
                className="rounded-pill px-3"
              >
                {category}
              </Button>
            ))}
          </div>
        </Container>
      </div>

      {/* Hero Banner */}
      <div className="hero-banner bg-gradient-primary text-white py-5 mb-4">
        <Container className="text-center">
          <h1 className="display-4 fw-bold mb-3">Welcome to ShopHub India</h1>
          <p className="lead mb-4">Discover amazing products at best prices with free shipping!</p>
          <Badge bg="light" text="dark" className="fs-6 px-3 py-2">
            <i className="bi bi-truck"></i> Free Shipping on orders over ₹50,000
          </Badge>
        </Container>
      </div>

      {/* Products Grid */}
      <Container className="py-4">
        <div className="d-flex justify-content-between align-items-center mb-4">
          <h3>
            <i className="bi bi-grid-3x3-gap-fill me-2"></i>
            Featured Products
          </h3>
          <Badge bg="secondary" pill className="fs-6">
            {filteredProducts.length} products found
          </Badge>
        </div>

        {loading ? (
          <div className="text-center py-5">
            <Spinner animation="border" variant="primary" />
            <p className="mt-3">Loading amazing products...</p>
          </div>
        ) : (
          <Row xs={1} sm={2} md={3} lg={4} className="g-4">
            {filteredProducts.map(product => (
              <Col key={product.id}>
                <Card className="h-100 shadow-sm product-card">
                  <div className="image-wrapper">
                    <Card.Img variant="top" src={product.image} className="product-img" />
                    {product.stock < 20 && (
                      <Badge bg="warning" className="stock-badge">Only {product.stock} left</Badge>
                    )}
                  </div>
                  <Card.Body className="d-flex flex-column">
                    <div className="d-flex justify-content-between align-items-start mb-2">
                      <Card.Title className="fs-6 fw-bold mb-0">{product.name}</Card.Title>
                      <Badge bg="info" pill>{product.brand}</Badge>
                    </div>
                    <Card.Text className="small text-muted">{product.description.substring(0, 80)}...</Card.Text>
                    <div className="rating mb-2">
                      {'★'.repeat(Math.floor(product.rating))}{'☆'.repeat(5 - Math.floor(product.rating))}
                      <span className="small text-muted ms-1">({product.rating})</span>
                    </div>
                    <div className="mt-auto">
                      <div className="d-flex justify-content-between align-items-center">
                        <h5 className="text-primary mb-0 fw-bold">{formatIndianRupee(product.price)}</h5>
                        <Button 
                          variant="primary" 
                          size="sm"
                          onClick={() => addToCart(product)}
                          disabled={product.stock === 0}
                          className="rounded-pill"
                        >
                          <i className="bi bi-cart-plus"></i> Add
                        </Button>
                      </div>
                    </div>
                  </Card.Body>
                </Card>
              </Col>
            ))}
          </Row>
        )}

        {filteredProducts.length === 0 && (
          <Alert variant="info" className="text-center">
            <i className="bi bi-emoji-frown fs-1"></i>
            <p className="mt-2">No products found. Try a different search or category!</p>
          </Alert>
        )}
      </Container>

      {/* Cart Modal */}
      <Modal show={showCart} onHide={() => setShowCart(false)} size="lg" centered>
        <Modal.Header closeButton className="bg-primary text-white">
          <Modal.Title>
            <i className="bi bi-cart3 me-2"></i>
            Your Shopping Cart ({getCartCount()} items)
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {cart.length === 0 ? (
            <div className="text-center py-5">
              <i className="bi bi-emoji-smile fs-1 text-muted"></i>
              <p className="mt-3">Your cart is empty. Start shopping!</p>
            </div>
          ) : (
            <Table responsive>
              <thead>
                <tr>
                  <th>Product</th>
                  <th>Price</th>
                  <th>Quantity</th>
                  <th>Total</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {cart.map(item => (
                  <tr key={item.id}>
                    <td className="align-middle">
                      <div className="d-flex align-items-center gap-2">
                        <img src={item.image} alt={item.name} style={{ width: '50px', height: '50px', objectFit: 'cover' }} />
                        <span className="fw-bold">{item.name}</span>
                      </div>
                    </td>
                    <td className="align-middle">{formatIndianRupee(item.price)}</td>
                    <td className="align-middle">
                      <div className="d-flex align-items-center gap-2">
                        <Button size="sm" variant="outline-secondary" onClick={() => updateQuantity(item.id, item.quantity - 1)}>-</Button>
                        <span className="fw-bold">{item.quantity}</span>
                        <Button size="sm" variant="outline-secondary" onClick={() => updateQuantity(item.id, item.quantity + 1)}>+</Button>
                      </div>
                    </td>
                    <td className="align-middle fw-bold">{formatIndianRupee(item.price * item.quantity)}</td>
                    <td className="align-middle">
                      <Button variant="link" className="text-danger" onClick={() => removeFromCart(item.id)}>
                        <i className="bi bi-trash"></i>
                      </Button>
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="table-active">
                  <td colSpan="3" className="text-end fw-bold">Grand Total:</td>
                  <td colSpan="2" className="fw-bold fs-5 text-primary">{formatIndianRupee(getCartTotal())}</td>
                </tr>
              </tfoot>
            </Table>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowCart(false)}>
            Continue Shopping
          </Button>
          {cart.length > 0 && (
            <Button variant="success" onClick={() => {
              setShowCart(false);
              setShowCheckout(true);
            }}>
              <i className="bi bi-credit-card"></i> Proceed to Checkout
            </Button>
          )}
        </Modal.Footer>
      </Modal>

      {/* Checkout Modal */}
      <Modal show={showCheckout} onHide={() => setShowCheckout(false)} size="lg" centered>
        <Modal.Header closeButton className="bg-success text-white">
          <Modal.Title>
            <i className="bi bi-clipboard-check me-2"></i>
            Checkout
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Row>
            <Col md={6}>
              <h5 className="mb-3">Order Summary</h5>
              <div className="bg-light p-3 rounded">
                {cart.map(item => (
                  <div key={item.id} className="d-flex justify-content-between mb-2">
                    <span>{item.name} x {item.quantity}</span>
                    <span>{formatIndianRupee(item.price * item.quantity)}</span>
                  </div>
                ))}
                <hr />
                <div className="d-flex justify-content-between fw-bold">
                  <span>Total:</span>
                  <span className="text-success">{formatIndianRupee(getCartTotal())}</span>
                </div>
              </div>
            </Col>
            <Col md={6}>
              <h5 className="mb-3">Shipping Details</h5>
              <Form>
                <Form.Group className="mb-2">
                  <Form.Control
                    type="text"
                    name="fullName"
                    placeholder="Full Name"
                    value={shippingDetails.fullName}
                    onChange={handleCheckoutInput}
                    required
                  />
                </Form.Group>
                <Form.Group className="mb-2">
                  <Form.Control
                    type="text"
                    name="address"
                    placeholder="Address"
                    value={shippingDetails.address}
                    onChange={handleCheckoutInput}
                    required
                  />
                </Form.Group>
                <Form.Group className="mb-2">
                  <Form.Control
                    type="text"
                    name="city"
                    placeholder="City"
                    value={shippingDetails.city}
                    onChange={handleCheckoutInput}
                    required
                  />
                </Form.Group>
                <Form.Group className="mb-2">
                  <Form.Control
                    type="text"
                    name="state"
                    placeholder="State"
                    value={shippingDetails.state}
                    onChange={handleCheckoutInput}
                  />
                </Form.Group>
                <Form.Group className="mb-2">
                  <Form.Control
                    type="text"
                    name="pincode"
                    placeholder="PIN Code"
                    value={shippingDetails.pincode}
                    onChange={handleCheckoutInput}
                    required
                  />
                </Form.Group>
                <Form.Group className="mb-2">
                  <Form.Control
                    type="tel"
                    name="phone"
                    placeholder="Phone Number"
                    value={shippingDetails.phone}
                    onChange={handleCheckoutInput}
                    required
                  />
                </Form.Group>
                <Form.Group className="mb-2">
                  <Form.Select name="paymentMethod" value={shippingDetails.paymentMethod} onChange={handleCheckoutInput}>
                    <option value="cod">Cash on Delivery</option>
                    <option value="online">Online Payment (UPI/Card)</option>
                  </Form.Select>
                </Form.Group>
              </Form>
            </Col>
          </Row>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowCheckout(false)}>
            <i className="bi bi-arrow-left"></i> Back
          </Button>
          <Button variant="success" onClick={placeOrder}>
            <i className="bi bi-check-circle"></i> Place Order
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Login Modal */}
      <Modal show={showLogin} onHide={() => setShowLogin(false)} centered>
        <Modal.Header closeButton className="bg-primary text-white">
          <Modal.Title>
            <i className="bi bi-person-circle me-2"></i>
            {isLogin ? 'Login' : 'Register'}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form onSubmit={handleLogin}>
            {!isLogin && (
              <Form.Group className="mb-3">
                <Form.Control
                  type="text"
                  placeholder="Full Name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  required
                />
              </Form.Group>
            )}
            <Form.Group className="mb-3">
              <Form.Control
                type="email"
                placeholder="Email Address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Control
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </Form.Group>
            <Button type="submit" variant="primary" className="w-100">
              {isLogin ? 'Login' : 'Register'}
            </Button>
          </Form>
          <div className="text-center mt-3">
            <Button variant="link" onClick={() => setIsLogin(!isLogin)}>
              {isLogin ? "Don't have an account? Register" : 'Already have an account? Login'}
            </Button>
          </div>
          <Alert variant="info" className="mt-3 small">
            <i className="bi bi-info-circle"></i> Demo: demo@example.com / demo
          </Alert>
        </Modal.Body>
      </Modal>

      {/* Footer */}
      <footer className="bg-dark text-white mt-5 py-4">
        <Container>
          <Row>
            <Col md={4}>
              <h5><i className="bi bi-shop"></i> ShopHub India</h5>
              <p className="small">Your one-stop destination for quality products at best prices.</p>
            </Col>
            <Col md={4}>
              <h5>Quick Links</h5>
              <ul className="list-unstyled small">
                <li><a href="#" className="text-white-50 text-decoration-none">About Us</a></li>
                <li><a href="#" className="text-white-50 text-decoration-none">Contact Us</a></li>
                <li><a href="#" className="text-white-50 text-decoration-none">Return Policy</a></li>
              </ul>
            </Col>
            <Col md={4}>
              <h5>Contact</h5>
              <p className="small mb-1"><i className="bi bi-envelope"></i> support@shophub.com</p>
              <p className="small"><i className="bi bi-telephone"></i> +91 98765 43210</p>
            </Col>
          </Row>
          <hr className="bg-secondary" />
          <p className="text-center small mb-0">&copy; 2025 ShopHub India. All rights reserved.</p>
        </Container>
      </footer>
    </div>
  );
}

export default App;